package dev.zomboid.turretpower;
import java.util.*;import dev.zomboid.survival.*;import com.entropy.tacz_turrets.turret.TurretEntity;
public class Checks {
 static int checks;static void ok(boolean b,String m){checks++;if(!b)throw new AssertionError(m);}
 public record P(int x,int y,int z){public double distSqr(P p){return (x-p.x)*(x-p.x)+(y-p.y)*(y-p.y)+(z-p.z)*(z-p.z);}public P offset(int a,int b,int c){return new P(x+a,y+b,z+c);}}
 public static class S {public String id;public S(String id){this.id=id;}public String getBlock(){return id;}public boolean is(Object tag){return id.contains("glass");}}
 public static class W {public long time;public boolean client,loaded=true,bedWorks=true;public Map<P,MachineEntity> machines=new HashMap<>();public Map<P,S> blocks=new HashMap<>();public List<Object> mobs=new ArrayList<>(),players=new ArrayList<>();public List<Object> sounds=new ArrayList<>();public boolean isClientSide(){return client;}public long getGameTime(){return time;}public boolean hasChunkAt(P p){return loaded;}public Object getBlockEntity(P p){return machines.get(p);}public S getBlockState(P p){return blocks.getOrDefault(p,new S("minecraft:air"));}public List<Object> getEntitiesOfClass(Class<?> c,Object box){return mobs;}public List<Object> players(){return players;}public W dimensionType(){return this;}public boolean bedWorks(){return bedWorks;}public void playSound(Object player,P pos,Object sound,Object channel,float volume,float pitch){sounds.add(sound);}}
 public static class Box {public Object inflate(double d){return this;}}
 public static class T {public final W w;public Object target;public double distance=16;public boolean visible=true,alive=true,enabled=true,gun=true,ammo=true;public int invulnerableTime;public T(W w){this.w=w;}public W level(){return w;}public P blockPosition(){return new P(0,0,0);}public boolean hasLineOfSight(Object t){return visible;}public T getSensing(){return this;}public boolean isAlive(){return alive;}public boolean isValidTarget(Object t){return enabled&&distance<=400;}public double distanceToSqr(Object t){return distance;}public Object getTarget(){return target;}public boolean isEnabled(){return enabled;}public boolean hasGun(){return gun;}public boolean gunHasAmmo(){return ammo;}public Object getUUID(){return this;}public Box getBoundingBox(){return new Box();}}
 public static class Mob extends T {public String kind="minecraft:zombie";public int hits;public Mob(W w){super(w);}public String getType(){return kind;}public void setTarget(Object t){target=t;}public void doHurtTarget(Object t){hits++;}}
 public static class Fire {public Object shooter;public boolean canceled;Fire(Object t){shooter=t;}public Object getShooter(){return shooter;}public boolean isCanceled(){return canceled;}public void setCanceled(boolean b){canceled=b;}}
 public static class Register {public Map<Object,Object> entries=new HashMap<>();public Object getRegistryKey(){return net.minecraft.core.registries.Registries.SOUND_EVENT;}public void register(Object key,Object id,java.util.function.Supplier<?> supplier){entries.put(id,supplier.get());}}
}
